function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw antioxidant
  ctx.fillStyle = 'blue';
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // Draw free radicals
  ctx.fillStyle = 'red';
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(W/2 + 50*Math.cos(t + i), H/2 + 50*Math.sin(t + i), 10, 0, 2*Math.PI);
    ctx.fill();
    ctx.stroke();
  }

  // Draw antioxidant fighting free radicals
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 50*Math.cos(t), H/2 + 50*Math.sin(t));
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 5;
  ctx.stroke();

  ctx.restore();
}
